<template><div class="wrap"><div class="page-head"><h1>Matches</h1><p class="muted">Today's fixtures, live scores and results.</p></div><div class="toolbar"><button v-for="x in tabs" :key="x.v" class="ghost" :class="{activeTab:tab===x.v}" @click="tab=x.v">{{x.l}}</button></div><div v-if="loading" class="empty">Loading matches…</div><div v-else-if="error" class="error">{{error}} <button class="ghost" @click="load">Try again</button></div><div v-else class="match-list"><div v-for="m in matches" :key="m._id" class="card match-card"><div class="match-league"><span>{{m.leagueId?.name||'Football'}}</span><span :class="m.status==='live'?'live':''">{{m.status==='live'?'● LIVE':m.status}}</span></div><div class="teams"><div class="team"><TeamLogo :src="m.homeTeamId?.logo" :name="m.homeTeamId?.name" size="lg"/><b>{{m.homeTeamId?.name||'Home'}}</b></div><div class="score"><strong v-if="m.status==='live'||m.status==='finished'">{{m.homeScore}} - {{m.awayScore}}</strong><strong v-else>vs</strong><small>{{format(m.kickoff)}}</small></div><div class="team"><TeamLogo :src="m.awayTeamId?.logo" :name="m.awayTeamId?.name" size="lg"/><b>{{m.awayTeamId?.name||'Away'}}</b></div></div></div><div v-if="!matches.length" class="empty">No matches found.</div></div></div></template>
<script setup lang="ts">import {onMounted,ref,watch} from 'vue';import {api} from '../services/api';import TeamLogo from '../components/TeamLogo.vue';const tabs=[{v:'today',l:'Today'},{v:'live',l:'Live'},{v:'finished',l:'Finished'},{v:'scheduled',l:'Upcoming'}],tab=ref('today'),matches=ref<any[]>([]),loading=ref(false),error=ref('');const format=(v:string)=>new Date(v).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});async function load(){loading.value=true;error.value='';try{const d=tab.value==='today'?await api.get('/matches/today'):tab.value==='live'?await api.get('/matches/live'):await api.get(`/matches?status=${tab.value}&limit=100`);matches.value=d.data||[]}catch(e:any){error.value=e.message||'Unable to load matches.'}finally{loading.value=false}}watch(tab,load);onMounted(load)</script>
